const initSqlJs = require('sql.js');
const fs = require('fs');

async function main() {
  const SQL = await initSqlJs();
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);

  // Get current reservation to build refund payment history
  const res = db.exec(\"SELECT payment_history_json FROM flight_bookings WHERE booking_id = 'A58410'\");
  const currentPayments = JSON.parse(res[0].values[0][0]);
  console.log('Current payment history:', JSON.stringify(currentPayments));

  // Add refund entries (negative amounts) for each original payment
  const refunds = currentPayments.map(p => ({ payment_id: p.payment_id, amount: -p.amount }));
  const updatedHistory = [...currentPayments, ...refunds];
  console.log('Updated payment history:', JSON.stringify(updatedHistory));

  // Update reservation status to cancelled and add refund to payment history
  db.run(
    \"UPDATE flight_bookings SET status = 'cancelled', payment_history_json = ? WHERE booking_id = 'A58410'\",
    [JSON.stringify(updatedHistory)]
  );

  // Verify the update
  const verify = db.exec(\"SELECT booking_id, status, payment_history_json FROM flight_bookings WHERE booking_id = 'A58410'\");
  const cols = verify[0].columns;
  const row = verify[0].values[0];
  const obj = {};
  cols.forEach((c, i) => obj[c] = row[i]);
  console.log('\\nUpdated reservation:');
  console.log(JSON.stringify(obj, null, 2));

  // Write changes back to disk
  const data = db.export();
  const buffer = Buffer.from(data);
  fs.writeFileSync('/workspace/world.db', buffer);
  console.log('\\nDatabase saved successfully.');

  db.close();
}
main().catch(console.error);
"
